import fs from 'node:fs';import path from 'node:path';import{fileURLToPath,pathToFileURL}from'node:url';
const repo=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..'),game=path.join(repo,'fengming-v2-scene-a'),out=path.join(game,'assets/hero-035/source');
const T=await import(pathToFileURL(path.join(game,'vendor/three/three.module.js'))),{createHero:createH34}=await import('./lib/linyan-h34-runtime.mjs');
let source=fs.readFileSync(path.join(game,'sample/hero.js'),'utf8').replace("from 'three'",`from '${pathToFileURL(path.join(game,'vendor/three/three.module.js'))}'`).replace(/from '(\.\.\/assets\/[^']+)'/g,(_,r)=>`from '${pathToFileURL(path.resolve(game,'sample',r))}'`);
const{createHero:createH35}=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
const viewport=[390,844],P=new T.Vector3(1.6206605404226109,.7069842713064673,-6.994434770474721),yaw=1.0773642551225169,camera=new T.PerspectiveCamera(39,390/844,.1,160);camera.position.copy(P).add(new T.Vector3(6,27,15));camera.lookAt(P);camera.updateMatrixWorld(true);
const names=['hips','chest','head','leftThigh','rightThigh','leftKnee','rightKnee','leftAnkle','rightAnkle','leftShoulder','rightShoulder','rightWrist'];
function sample(create,p){const h=create(),g=new T.Group();g.position.copy(P);g.rotation.y=yaw;g.add(h.group);h.update(0,{attackProgress:p});g.updateMatrixWorld(true);const bones=Object.fromEntries(h.body.skeleton.bones.map(b=>[b.name,b])),data={};for(const name of names){const b=bones[name],world=b.getWorldPosition(new T.Vector3()),pixel=world.clone().project(camera);data[name]={localPosition:b.position.toArray(),localEuler:b.rotation.toArray().slice(0,3),world:world.toArray(),pixel:[(pixel.x+1)*390/2,(1-pixel.y)*844/2]};}return data;}
const rows=[];for(const p of [0,.12,.24,.34,.44,.60,.72,.80,.88,1]){const old=sample(createH34,p),now=sample(createH35,p),delta={};for(const n of names)delta[n]={screenH35MinusH34:now[n].pixel.map((v,i)=>v-old[n].pixel[i]),worldDistance:new T.Vector3().fromArray(now[n].world).distanceTo(new T.Vector3().fromArray(old[n].world))};rows.push({phase:p,H34:old,H35:now,delta});}
const report={scope:'CPU actual bone anchors projected into unchanged normal 390x844/FOV39/offset6,27,15; H34 and H35 same parent pose, mesh, scale and sword socket',viewport,player:P.toArray(),yaw,rows};fs.writeFileSync(path.join(out,'normal-pose-deltas.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(rows.filter(r=>[.24,.44,.80].includes(r.phase)).map(r=>({p:r.phase,hipsH34:r.H34.hips.localPosition,hipsH35:r.H35.hips.localPosition,hipYawH35:r.H35.hips.localEuler[1],chestYawH35:r.H35.chest.localEuler[1],kneeAnglesH35:[r.H35.leftKnee.localEuler[0],r.H35.rightKnee.localEuler[0]].map(v=>v*180/Math.PI),anklePixelDelta:[r.delta.leftAnkle.screenH35MinusH34,r.delta.rightAnkle.screenH35MinusH34]})),null,2));
